const lang = ref(localStorage.getItem('eaia-language') || 'zh-CN')
const zh = computed(() => lang.value === 'zh-CN')
const busy = ref(false), message = ref(''), error = ref(''), search = ref('')
const TEXT={zh:{brand:'装备与英雄数据库',dictionary:'游戏数据',equipment:'已有装备',heroes:'英雄图鉴',recommendation:'装备推荐',scanner:'识别装备',add:'新增',edit:'编辑',del:'删除',save:'保存',cancel:'取消',search:'搜索',actions:'操作',seq:'序号',slot:'部位',set:'套装',quality:'品质',level:'强化',main:'主词条',sub:'副词条',status:'状态',upload:'上传 HeroCore',template:'下载数据模板',attr:'英雄属性',skills:'技能资料',talents:'天赋/额外机制',core:'HeroCore 可计算',nocore:'暂无 HeroCore',run:'开始配装计算',running:'HeroCore 计算中…',targetDef:'木桩防御',enemies:'目标数量',topK:'结果数量',trials:'精算随机次数',candidate:'每部位候选数',minRelevantSubstats:'至少相关副词条',policy:'终结技策略',ed60:'等效60秒伤害',actual60:'实际前60秒',panel:'最终面板',build:'装备组合',delta:'距第一名',connect:'检测连接',start:'开始识别',stop:'停止',progress:'识别进度'},en:{brand:'Equipment & Hero Database',dictionary:'Game Data',equipment:'Inventory',heroes:'Hero Codex',recommendation:'Builds',scanner:'Scanner',add:'Add',edit:'Edit',del:'Delete',save:'Save',cancel:'Cancel',search:'Search',actions:'Actions',seq:'#',slot:'Slot',set:'Set',quality:'Quality',level:'Enhance',main:'Main Stat',sub:'Sub Stats',status:'Status',upload:'Upload HeroCore',template:'Download Template',attr:'Attributes',skills:'Skills',talents:'Talents / Extra Mechanics',core:'HeroCore Ready',nocore:'No HeroCore',run:'Run HeroCore Search',running:'Calculating…',targetDef:'Target DEF',enemies:'Targets',topK:'Results',trials:'Refine Trials',candidate:'Candidates / Slot',minRelevantSubstats:'Min Relevant Substats',policy:'Ultimate Policy',ed60:'Equivalent 60s',actual60:'Actual First 60s',panel:'Final Panel',build:'Equipment Build',delta:'Gap to Best',connect:'Check Connection',start:'Start Scan',stop:'Stop',progress:'Scan Progress'}}
